export const translations = {
  "zh-CN": zhCN,
  "en-US": enUS,
  "ja-JP": jaJP,
  "vi-VN": viVN,
} satisfies Record<Locale, Record<keyof typeof zhCN, string>>;

export type TranslationKey = keyof typeof zhCN;

export const LOCALE_LABEL_KEYS = {
  "zh-CN": "locale.zhCN",
  "en-US": "locale.enUS",
  "ja-JP": "locale.jaJP",
  "vi-VN": "locale.viVN",
} satisfies Record<Locale, TranslationKey>;

export function isLocale(value: string | null | undefined): value is Locale {
  return LOCALES.includes(value as Locale);
}

export function resolveLocale(value: string | null | undefined): Locale {
  return isLocale(value) ? value : DEFAULT_LOCALE;
}

export function interpolate(template: string, params: TranslationParams = {}): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => {
    const value = params[key];
    return value === undefined ? match : String(value);
  });
}

export function translate(locale: Locale, key: TranslationKey, params?: TranslationParams): string {
  return interpolate(translations[locale][key] ?? translations[DEFAULT_LOCALE][key], params);
}
